def crude_birth_rate(births, population):
    if population <= 0.0:
        return 0.0
    return births / population * 1000.0



def crude_death_rate(deaths, population):
    if population <= 0.0:
        return 0.0
    return deaths / population * 1000.0



def natural_increase_rate(cbr, cdr):
    return cbr - cdr






def total_fertility_rate(age_specific_rates_sum, interval):
    return age_specific_rates_sum * interval



def infant_mortality_rate(infant_deaths, live_births):
    if live_births <= 0.0:
        return 0.0
    return infant_deaths / live_births * 1000.0



def life_expectancy_approx(total_person_years, population):
    if population <= 0.0:
        return 0.0
    return total_person_years / population






def dependency_ratio(young, old, working_age):
    if working_age <= 0.0:
        return 0.0
    return (young + old) / working_age * 100.0



def sex_ratio(males, females):
    if females <= 0.0:
        return 0.0
    return males / females * 100.0






def population_growth_rate(births, deaths, net_migration, population):
    if population <= 0.0:
        return 0.0
    return (births - deaths + net_migration) / population * 100.0



def doubling_time(growth_rate_pct):
    if growth_rate_pct <= 0.0:
        return 0.0
    return 70.0 / growth_rate_pct






def urbanization_rate(urban_pop, total_pop):
    if total_pop <= 0.0:
        return 0.0
    return urban_pop / total_pop * 100.0



def median_age_estimate(young_pct, old_pct):
    return 15.0 + 50.0 * (1.0 - young_pct / 100.0) - 10.0 * (old_pct / 100.0)
